func (q *Queries) UpsertBundleVersion(ctx context.Context, arg UpsertBundleVersionParams) error {
	_, err := q.db.Exec(ctx, upsertBundleVersion,
		arg.BundleID,
		arg.Version,
		arg.Content,
		arg.Notes,
		arg.CreatedAt,
	)
	return err
}

const upsertOfficialBundle = `-- name: UpsertOfficialBundle :execrows
INSERT INTO bundles (
    id,
    name,
    description,
    version,
    created_at,
    updated_at
) VALUES (
    $1, $2, $3, $4, $5, $6
)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    version = EXCLUDED.version,
    updated_at = EXCLUDED.updated_at
WHERE bundles.owner_user_id IS NULL
`

type UpsertOfficialBundleParams struct {
	ID          string
	Name        string
	Description string
	Version     int32
	CreatedAt   pgtype.Timestamp
	UpdatedAt   pgtype.Timestamp
}

func (q *Queries) UpsertOfficialBundle(ctx context.Context, arg UpsertOfficialBundleParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertOfficialBundle,
		arg.ID,
		arg.Name,
		arg.Description,
		arg.Version,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
